func (q *Queries) UpdateUser(ctx context.Context, arg UpdateUserParams) (User, error) {
	row := q.db.QueryRow(ctx, updateUser, arg.ID, arg.Name, arg.Email)
	var i User
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Email,
		&i.PasswordHash,
		&i.Role,
		&i.AuthProvider,
		&i.AuthProviderID,
		&i.ExternalID,
		&i.PersonalWorkspaceID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Status,
		&i.SuspendedAt,
		&i.SuspendedReason,
		&i.DirectorySyncedAt,
		&i.Locale,
	)
	return i, err
}

